<script lang="ts">
 import{onMount,onDestroy,tick}from'svelte';import{api,listen,rows,text,compact,cost,number,type Row}from'../lib/api';import{tr}from'../lib/i18n';
 import{modelName,effort,speed,requestStatus,fullTime}from'./logFormat';import{journeyBlocks,journeyTitle,journeyDuration,eventFields,fileAction}from'./journey';import JourneyEvent from './JourneyEvent.svelte';import JourneyPicker from './JourneyPicker.svelte';import JourneyCommand from './JourneyCommand.svelte';import JourneyIcon from './JourneyIcon.svelte';
 export let client="codex";export let revision:any;export let onerror:((e:any)=>void)|undefined;
 let projects:Row[]=[],threads:Row[]=[],requests:Row[]=[],project='',thread:Row={},request:Row={},summary:Row={},selected:Row={},events:Row[]=[];
 let threadNext='',requestPage=1,requestPages=1,next='',scope='',cursors=[''],scopeLabel='',busy=false,error='',ready=false,lastRevision:any;
 let catalogTicket=0,threadTicket=0,flowTicket=0,collapsed=new Set<string>(),catalogSignature='',flowSignature='';let pane:HTMLDivElement,flowScroll:HTMLDivElement;
 let split=48/77,drag:{x:number;split:number;width:number}|null=null;
 let ancestors:{scope:string;label:string;cursors:string[];scroll:number}[]=[];
 $: blocks=journeyBlocks(events);
 $: if(ready&&revision!==lastRevision){lastRevision=revision;if(document.visibilityState==='visible'){void loadCatalog(project);if(thread.id)void loadThread()}}
 $: requestFields=[[tr('费用'),cost(request.cost_usd)],['Token',compact(request.total_tokens)],[tr('模型调用'),text(request.call_count)],[tr('耗时'),journeyDuration(request.duration_ms)],[tr('模型'),modelName(request.model)],[tr('推理强度'),effort(request.reasoning_effort)||'—'],[tr('速度'),speed(request.service_tier)],[tr('状态'),requestStatus(request)],[tr('开始'),fullTime(request.started_at??request.timestamp)],[tr('结束'),fullTime(request.ended_at)]];
 onMount(()=>{ready=true;lastRevision=revision;void loadCatalog('');const stop=listen('codexio:clock',()=>{if(document.visibilityState==='visible')void loadCatalog(project)});return stop});
 onDestroy(()=>{ready=false;catalogTicket++;threadTicket++;flowTicket++});
 async function loadCatalog(target:string,before='',preferred?:Row){const ticket=++catalogTicket;try{const data=await api('GetClientJourneyCatalog',client,target,before);if(ticket!==catalogTicket)return;if(!project&&rows(data.threads).length){const latest=rows(data.threads)[0];project=String(latest.project_id??'chats');await loadCatalog(project,'',latest);return}projects=rows(data.projects);threadNext=text(data.next,'');const signature=JSON.stringify(rows(data.threads).map(t=>[t.id,t.title,t.project_id]));if(signature!==catalogSignature){catalogSignature=signature;threads=rows(data.threads)}if(preferred)chooseThread(preferred);else if(!thread.id&&threads.length)chooseThread(threads[0]);}catch(e){if(ticket===catalogTicket)error=String(e)}}
 function chooseProject(id:string){error='';project=id;thread={};request={};selected={};requests=[];events=[];flowSignature='';threads=[];catalogSignature='';threadTicket++;flowTicket++;void loadCatalog(project)}
 function chooseThread(row:Row){error='';thread=row;request={};selected={};events=[];flowSignature='';scope='';ancestors=[];cursors=[''];flowTicket++;void loadThread(1)}
 async function loadThread(page=requestPage){const id=thread.id,ticket=++threadTicket;try{const data=await api('GetJourneyThread',id,page);if(ticket!==threadTicket||thread.id!==id)return;requests=rows(data.requests);summary=data.summary??{};requestPage=Number(data.page??page);requestPages=Number(data.pages??1);if(!request.id&&requests.length)chooseRequest(requests[0]);else{const current=requests.find(r=>r.id===request.id);if(current){request=current;void loadFlow(cursors.at(-1)??'')}}}catch(e){if(ticket===threadTicket)error=String(e)}}
 function chooseRequest(row:Row){error='';request=row;scope='';ancestors=[];selected={};events=[];flowSignature='';cursors=[''];collapsed=new Set();void loadFlow('',0)}
 async function loadFlow(cursor='',scroll?:number){if(!request.id)return;const id=request.id,child=scope,ticket=++flowTicket;busy=!events.length;try{const data=await api('GetJourneyFlow',id,child,cursor);if(ticket!==flowTicket||request.id!==id||scope!==child)return;const offset=scroll??flowScroll?.scrollTop??0;const signature=id+'|'+child+'|'+cursor+'|'+JSON.stringify(data);if(signature!==flowSignature){flowSignature=signature;events=rows(data.events);selected=events.find(e=>e.id===selected.id)??events.find(e=>e.kind==='model')??events[0]??{};await tick();if(ticket===flowTicket&&flowScroll)flowScroll.scrollTop=offset}next=text(data.next,'');error='';}catch(e){if(ticket===flowTicket)error=String(e)}finally{if(ticket===flowTicket)busy=false}}
 function chooseAgent(event:Row){ancestors=[...ancestors.slice(-7),{scope,label:scopeLabel,cursors:[...cursors],scroll:flowScroll?.scrollTop??0}];scope=event.agent_id;scopeLabel=text(event.preview,tr('子代理'));cursors=[''];selected={};events=[];flowSignature='';void loadFlow('',0)}
 function back(){const previous=ancestors.at(-1);ancestors=ancestors.slice(0,-1);scope=previous?.scope??'';scopeLabel=previous?.label??'';cursors=previous?.cursors??[''];selected={};events=[];flowSignature='';void loadFlow(cursors.at(-1)??'',previous?.scroll??0)}
 function toggle(row:Row){selected=row;const set=new Set(collapsed);set.has(row.id)?set.delete(row.id):set.add(row.id);collapsed=set}
 async function open(){try{await api('OpenJourneySource',client,thread.id)}catch(e){onerror?.(e)}}
 // Same stable viewport coordinates as Logs.svelte's native column handles.
 function begin(event:PointerEvent){if(event.button!==0)return;event.preventDefault();drag={x:event.clientX,split,width:pane.clientWidth}}
 function move(event:PointerEvent){if(drag)split=Math.max(.38,Math.min(.75,drag.split+(event.clientX-drag.x)/drag.width))}
 function end(){drag=null}
 function resizeKey(e:KeyboardEvent){if(!["ArrowLeft","ArrowRight"].includes(e.key))return;e.preventDefault();split=Math.max(.38,Math.min(.75,split+(e.key==="ArrowRight" ? .01 : -.01)))}
 function requestSelection(id:string){if(id==='__older'){void loadThread(requestPage+1);return}if(id==='__newer'){void loadThread(requestPage-1);return}const row=requests.find(r=>r.id===id);if(row)chooseRequest(row)}
 function threadSelection(id:string){if(id==='__more'){void loadCatalog(project,threadNext);return}const row=threads.find(r=>r.id===id);if(row)chooseThread(row)}
</script>
<svelte:window onpointermove={move} onpointerup={end} onpointercancel={end} onblur={end}/>
<section class="journey">
 <h3>{tr('执行行程')}</h3>
 <div class="journey-filters"><div class="project-filter"><JourneyPicker label={tr('项目')} title={text(projects.find(p=>p.id===project)?.name,tr('项目'))} value={project} options={projects.map(p=>({id:String(p.id),title:p.id==='chats'?tr('聊天'):text(p.name)}))} onselect={chooseProject}/></div><div class="thread-filter"><JourneyPicker label={tr('线程')} title={text(thread.title,tr('线程'))} value={String(thread.id??'')} options={[...threads.map(t=>({id:String(t.id),title:text(t.title)})),...(threadNext?[{id:'__more',title:tr('显示更多')}]:[])]} onselect={threadSelection}/></div></div>
 {#if error}<p class="journey-error">{error}</p>{/if}
 {#if !thread.id}<p class="muted">{tr('暂无本机聊天记录')}</p>
 {:else}<div class="journey-panes" bind:this={pane} style={`--journey-split:${split*100}%`} class:resizing={!!drag}>
  <div class="journey-main">
   <div class="request-picker"><JourneyPicker label={tr('选择用户请求')} title={text(request.prompt_preview)} value={String(request.id??'')} options={[...requests.map(r=>({id:String(r.id),title:text(r.prompt_preview)})),...(requestPage>1?[{id:'__newer',title:tr('较新的请求')}]:[]),...(requestPage<requestPages?[{id:'__older',title:tr('较早的请求')}]:[])]} onselect={requestSelection}/></div>
   {#if scope}<div class="scope"><button class="quiet" onclick={back}>‹ {tr('返回主行程')}</button><span>{scopeLabel}</span></div>{/if}
   <div class="flow-scroll" bind:this={flowScroll}>
    {#if busy}<p class="muted">{tr('正在加载')}</p>{/if}
    {#each blocks as block(block.id)}<div class="model-group" class:model-call={!!block.model}>
     {#if block.model}<button class="model-heading" class:chosen={selected.id===block.model.id} aria-expanded={!collapsed.has(block.id)} onclick={()=>toggle(block.model!)}><JourneyIcon kind="model"/><strong>{journeyTitle(block.model)}</strong><span>{cost(block.model.cost_usd)} · {compact(block.model.tokens)}{number(block.model.tokens)===null?'':' Token'}</span><span class="model-chevron"><JourneyIcon kind={collapsed.has(block.id)?'chevronRight':'chevronDown'} size={12}/></span></button>{/if}
     {#if !block.model||!collapsed.has(block.id)}<div class="model-children">{#each block.items as event(event.id)}<JourneyEvent {event} selected={String(selected.id??'')} onselect={e=>selected=e} onagent={chooseAgent}/>{/each}</div>{/if}
    </div>{/each}
    {#if !busy&&!blocks.length}<p class="muted">—</p>{/if}
    <div class="flow-pages"><button disabled={cursors.length<=1} onclick={()=>{cursors=cursors.slice(0,-1);void loadFlow(cursors.at(-1)??'',0)}}>{tr('上一页')}</button><span>{cursors.length}</span><button disabled={!next} onclick={()=>{cursors=[...cursors,next];void loadFlow(next,0)}}>{tr('下一页')}</button></div>
   </div>
   <footer><button disabled={!thread.id} onclick={open}>{tr(client==='claude_code'?'查看本地记录 ↗':'在 Codex 中继续 ↗')}</button></footer>
  </div>
  <button class="pane-handle" aria-label={tr('调整详情栏宽度')} onpointerdown={begin} onkeydown={resizeKey} ondblclick={()=>split=48/77}></button>
  <aside class="journey-inspector"><h4>{text(thread.title)}</h4><div class="metrics">{#each [[tr('费用'),cost(summary.cost_usd)],['Token',compact(summary.tokens)],[tr('请求'),text(summary.requests)],[tr('模型调用'),text(summary.calls)]] as [label,value]}<div><small>{label}</small><strong>{value}</strong></div>{/each}</div>
   <section><h4 class="request-title">{text(request.prompt_preview)}</h4><dl>{#each requestFields as [label,value]}<div><dt>{label}</dt><dd>{value}</dd></div>{/each}</dl></section>
   {#if selected.id}<section><div class="step-heading"><JourneyIcon kind={selected.kind}/><h4>{journeyTitle(selected)}</h4>{#if selected.command}<JourneyCommand command={selected.command} tool={journeyTitle(selected)}/>{/if}</div>{#if selected.preview}<p class="event-preview">{selected.preview}</p>{/if}<dl>{#each eventFields(selected) as [label,value]}<div><dt>{label}</dt><dd>{value}</dd></div>{/each}</dl>{#each rows(selected.files) as file}<div class="file"><span>{fileAction(file.action)}</span><span>{text(file.path)}{file.destination?' → '+file.destination:''}</span></div>{/each}</section>{/if}
  </aside>
 </div>{/if}
</section>
<style>
 .journey{container-type:inline-size;min-width:0;display:flex;flex-direction:column;gap:16px}.journey h3{font-size:18px;margin:0}.journey-filters{display:flex;gap:12px;min-width:0}.project-filter{width:180px;min-width:0}.thread-filter{width:320px;max-width:calc(100% - 192px);min-width:0}.journey-panes{display:grid;grid-template-columns:minmax(300px,var(--journey-split)) minmax(230px,1fr);height:clamp(320px,calc(100dvh - 320px),650px);grid-template-rows:minmax(0,1fr);position:relative;border:1px solid var(--border);border-radius:14px;overflow:hidden;min-width:0}.journey-main{display:flex;flex-direction:column;min-height:0;min-width:0}.request-picker{flex:none;padding:14px;border-bottom:1px solid var(--border)}.flow-scroll{padding:14px 14px 24px;overflow:auto;min-height:0;flex:1;scrollbar-gutter:stable}.model-group{border:1px solid var(--border);border-radius:10px;overflow:hidden;margin-bottom:12px}.model-group.model-call{border-color:color-mix(in srgb,#7C68B6 26%,var(--border))}.model-heading{display:flex;gap:8px;align-items:center;width:100%;padding:12px;border:0;border-radius:0;background:color-mix(in srgb,#7C68B6 10%,var(--bg));font-size:12px}.model-heading strong{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;text-align:left;font-size:13px;font-weight:500}.model-heading>span{white-space:nowrap;font-variant-numeric:tabular-nums}.model-heading.chosen,.model-heading:hover{background:color-mix(in srgb,#7C68B6 17%,var(--bg))}.model-chevron{font-size:13px;color:var(--muted)}.model-children{padding:6px 10px}.model-heading+.model-children{border-top:1px solid var(--border)}.flow-pages{display:flex;align-items:center;justify-content:space-between;font-size:11px;padding:8px 0}.flow-pages button{font-size:11px}footer{flex:none;padding:12px;display:flex;justify-content:flex-end;border-top:1px solid var(--border)}footer button{font-size:12px}.scope{flex:none;padding:10px 14px;display:flex;gap:10px;font-size:11px;color:var(--muted)}.scope button{font-size:11px}.pane-handle{position:absolute;left:calc(var(--journey-split) - 4px);width:8px;min-width:8px;height:100%;top:0;padding:0;border:0;border-radius:0;background:transparent;z-index:2;cursor:col-resize;touch-action:none}.pane-handle::after{content:'';position:absolute;left:3px;top:0;bottom:0;width:1px;background:var(--border)}.pane-handle:hover::after{background:var(--text)}.resizing{user-select:none}.journey-inspector{min-height:0;padding:16px;overflow:auto;min-width:0;font-size:12px;scrollbar-gutter:stable}h4{font-size:13px;font-weight:500;margin:0 0 14px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:8px}.metrics>div{padding:9px;background:var(--surface);border:1px solid var(--border);border-radius:9px;min-width:0}.metrics small{display:block;font-size:11px;color:var(--muted);margin-bottom:5px}.metrics strong{font-size:16px;font-weight:500;font-variant-numeric:tabular-nums}.journey-inspector section{border-top:1px solid var(--border);padding-top:17px;margin-top:18px}.request-title{display:-webkit-box;-webkit-line-clamp:4;line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;line-height:1.5}dl{margin:0}dl>div{display:flex;gap:12px;justify-content:space-between;margin-bottom:10px}dt{color:var(--muted);flex-shrink:0}dd{margin:0;min-width:0;overflow-wrap:anywhere;text-align:right;font-variant-numeric:tabular-nums}.file{display:flex;gap:8px;font-size:11px;margin-top:7px;overflow-wrap:anywhere}.file>span:first-child{color:var(--muted);flex:none}.event-preview{font-size:12px;line-height:1.55;white-space:pre-wrap;overflow-wrap:anywhere;margin-bottom:14px}.journey-error{font-size:12px;color:var(--muted)}.step-heading{display:flex;align-items:center;gap:7px;margin-bottom:14px}.step-heading h4{margin:0;min-width:0;overflow-wrap:anywhere}@container(max-width:620px){.journey-panes{grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto;height:auto}.journey-main{height:clamp(320px,calc(100dvh - 320px),650px)}.journey-inspector{max-height:450px;border-top:1px solid var(--border)}.pane-handle{display:none}}
</style>
